/**
 * emit to subscription queries of type FindPaymentProcessor,
 * but only if the id matches
 *
 * @param		entity	PaymentProcessor
 */
	protected void emitFindPaymentProcessor( PaymentProcessor entity ) {
		LOGGER.info("handling emitFindPaymentProcessor" );
		
	    queryUpdateEmitter.emit(FindPaymentProcessorQuery.class,
	                            query -> query.getFilter().getPaymentProcessorId().equals(entity.getPaymentProcessorId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPaymentProcessor
	 * 
	 * @param		entity	PaymentProcessor
	 */
	protected void emitFindAllPaymentProcessor( PaymentProcessor entity ) {
		LOGGER.info("handling emitFindAllPaymentProcessor" );
		
	    queryUpdateEmitter.emit(FindAllPaymentProcessorQuery.class,
	                            query -> true,
	                            entity);
	}

